function findMin(nums: number[]): number {
  let lo = 0;
  let hi = nums.length - 1;

  // Минимум всегда лежит на отрезке [lo, hi]
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);

    if (nums[mid] > nums[hi]) {
      // Между mid и hi есть «излом» — минимум строго правее mid
      lo = mid + 1;
    } else {
      // Отрезок [mid, hi] возрастает — минимум это mid или левее
      hi = mid;
    }
  }

  return nums[lo];
}

// Время: O(log n)
// Память: O(1)
